package com.arena.login.controller;
import com.arena.login.service.TokenService;import org.junit.jupiter.api.Test;import org.springframework.http.*;import org.springframework.mock.web.*;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.web.client.*;import java.net.URI;import java.nio.charset.StandardCharsets;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class StaffRegistrationProxyTest {
 @Test void combinedRegistrationAndAvailabilityForwardOneAuthenticatedRequestWithUnchangedBody()throws Exception{for(String path:new String[]{"/api/academy/staff/registration","/api/academy/staff/login-availability"}){var core=mock(RestTemplate.class);var c=new TokenController(mock(TokenService.class),core);ReflectionTestUtils.setField(c,"coreUrl","http://example.invalid");var r=new MockHttpServletRequest("POST",path);r.setContentType("application/json");byte[] body="{\"requestId\":\"11111111-1111-4111-8111-111111111111\",\"username\":\"coach\",\"email\":\"coach@example.test\"}".getBytes(StandardCharsets.UTF_8);r.setContent(body);var session=new MockHttpSession();session.setAttribute("ACCESS_TOKEN","unit-test-placeholder");session.setAttribute("LAST_PRESENCE_TOUCH",System.currentTimeMillis());when(core.exchange(any(URI.class),eq(HttpMethod.POST),any(HttpEntity.class),eq(byte[].class))).thenReturn(ResponseEntity.ok("{}".getBytes()));assertEquals(200,c.proxyRequest(r,session).getStatusCode().value());var captured=org.mockito.ArgumentCaptor.forClass(HttpEntity.class);verify(core,times(1)).exchange(any(URI.class),eq(HttpMethod.POST),captured.capture(),eq(byte[].class));assertArrayEquals(body,(byte[])captured.getValue().getBody());assertEquals("Bearer unit-test-placeholder",captured.getValue().getHeaders().getFirst("Authorization"));}}
 @Test void distinctCredentialErrorsRemainSafeAndFieldSpecificThroughBff()throws Exception{for(String code:new String[]{"DUPLICATE_USERNAME","DUPLICATE_EMAIL"}){var core=mock(RestTemplate.class);var c=new TokenController(mock(TokenService.class),core);ReflectionTestUtils.setField(c,"coreUrl","http://example.invalid");var r=new MockHttpServletRequest("POST","/api/academy/staff/registration");var s=new MockHttpSession();s.setAttribute("ACCESS_TOKEN","unit-test-placeholder");s.setAttribute("LAST_PRESENCE_TOUCH",System.currentTimeMillis());when(core.exchange(any(URI.class),eq(HttpMethod.POST),any(HttpEntity.class),eq(byte[].class))).thenThrow(HttpClientErrorException.create(HttpStatus.CONFLICT,"Conflict",HttpHeaders.EMPTY,("{\"errorCode\":\""+code+"\",\"description\":\"internal diagnostic\"}").getBytes(StandardCharsets.UTF_8),StandardCharsets.UTF_8));var response=c.proxyRequest(r,s);assertEquals(409,response.getStatusCode().value());var result=new String(response.getBody(),StandardCharsets.UTF_8);assertTrue(result.contains(code));assertFalse(result.contains("internal diagnostic"));assertTrue(result.contains("fieldErrors"));assertTrue(result.contains(code.equals("DUPLICATE_USERNAME")?"username":"email"));}}
 @Test void unauthenticatedAvailabilityNeverReachesCore()throws Exception{var core=mock(RestTemplate.class);var c=new TokenController(mock(TokenService.class),core);ReflectionTestUtils.setField(c,"coreUrl","http://example.invalid");var r=new MockHttpServletRequest("POST","/api/academy/staff/login-availability");assertEquals(401,c.proxyRequest(r,new MockHttpSession()).getStatusCode().value());verify(core,never()).exchange(any(URI.class),any(HttpMethod.class),any(),eq(byte[].class));}
}
